$studentTable=function(bool $short=false)use($myStudents,$c,$e,$cid){echo '<div class="scroll"><table class="record-table" id="company-student-table"><thead><tr><th>Alumno/a</th><th>Grupo</th><th>Periodo previsto</th>'.($short?'':'<th>Centro de trabajo</th><th>Tutor empresarial</th>').'<th>Acción</th></tr></thead><tbody>';foreach($myStudents as $id=>$st){$g=$c['groups'][$st['group']]??[];echo '<tr><td>'.h($st['name']).'</td><td>'.h($g['name']??'').'</td><td>'.h(($g['start']??'').' — '.($g['end']??'')).'</td>';if(!$short)echo '<td>'.h($e['sites'][$st['site']??'']['name']??'Sin indicar').'</td><td>'.h($e['tutors'][$st['tutor']??'']['name']??'Sin indicar').'</td>';echo '<td><a class="button secondary" href="'.h(panel_url('portal',$cid,'students').'&sid='.rawurlencode((string)$id)).'">Abrir</a></td></tr>';}echo '</tbody></table></div>';if(!$myStudents)echo '<p>No hay alumnado asignado actualmente.</p>';};
$nextPanel=function()use($next,$myStudents){echo '<section class="card"><h2>Próximas acciones</h2>';foreach(array_slice($next,0,5,true) as $r)echo '<p class="portal-task"><strong>'.h($r['next']).'</strong> · '.h($myStudents[$r['student']]['name']).' · '.h($r['note']).'</p>';if(!$next)echo '<p class="muted">No hay acciones programadas.</p>';echo '</section>';};
